/**
 * Extract the incoming Telegram update from the webhook payload.
 *
 * Authorization: Telegram signs the webhook with the header
 * X-Telegram-Bot-Api-Secret-Token (looked up case-insensitively). The n8n
 * assembly passes process.env.TELEGRAM_WEBHOOK_SECRET. A mismatch emits an
 * EMPTY array — a silent drop, because responseMode onReceived already
 * returned the immediate 200 (RNF-01) before this node runs.
 * Outputs ONE item { chat_id, text, received_at } or an EMPTY array when the
 * update carries no text message. Never throws.
 */
function isAuthorized(headers, secret) {
  if (!headers || typeof headers !== 'object') return false;
  if (typeof secret !== 'string' || !secret) return false;
  const key = Object.keys(headers).find(
    (name) =>
      typeof name === 'string' &&
      name.toLowerCase() === 'x-telegram-bot-api-secret-token'
  );
  if (!key) return false;
  const value = headers[key];
  return typeof value === 'string' && value === secret;
}

/**
 * Pure parser: one Telegram update -> ONE item { chat_id, text, received_at }
 * or an EMPTY array (unauthorized, no message, non-text message).
 * Never throws: malformed payloads are dropped silently.
 */
function parseTelegramUpdate(update, headers, secret) {
  if (!isAuthorized(headers, secret)) return [];
  if (!update || typeof update !== 'object') return [];
  const message = update.message;
  if (!message || typeof message !== 'object') return [];
  const text = typeof message.text === 'string' ? message.text.trim() : '';
  if (!text) return []; // non-text message (photo, sticker, ...) -> drop
  const chat =
    message.chat &&
    (typeof message.chat.id === 'string' || typeof message.chat.id === 'number')
      ? String(message.chat.id)
      : '';
  if (!chat) return [];
  return [
    {
      json: {
        chat_id: chat,
        text: text,
        received_at:
          message.date && Number.isFinite(Number(message.date))
            ? new Date(Number(message.date) * 1000).toISOString()
            : new Date().toISOString()
      }
    }
  ];
}

// --- n8n data assembly (guarded so the test harness can load the functions) ---
if (typeof $input !== 'undefined') {
  try {
    const items = $input.all();
    for (let i = 0; i < items.length; i++) {
      const item = items[i];
      const json = item && item.json ? item.json : item;
      const headers =
        json && json.headers && typeof json.headers === 'object' ? json.headers : {};
      const update =
        json && json.body && typeof json.body === 'object' ? json.body : json;
      const out = parseTelegramUpdate(
        update,
        headers,
        process.env.TELEGRAM_WEBHOOK_SECRET
      );
      if (out.length) return out; // ONE item per webhook payload
    }
  } catch (err) {
    return []; // malformed payload -> drop, never throw
  }
  return [];
}

/**
 * US-04 — Consulta de stock (fuzzy, LLM-free).
 *
 * SCORE = 0.60 * tokenSimilarity + 0.30 * coverage + 0.10 * doseBonus
 *   - tokenSimilarity: mean over query tokens of the best similarity found in the
 *     pool of tokens from nombre_comercial + principio_activo + dosis.
 *     Shortcuts on the candidate token: exact = 1.0, starts with query = 0.92,
 *     contains query = 0.85, otherwise levenshtein similarity.
 *   - coverage: fraction of query tokens whose best similarity is >= COVERAGE_TOKEN_MIN.
 *   - doseBonus: 1 (row dose matches the query dose token), 0.5 (query has no dose
 *     token), 0 (query dose missing in the row); a missing dose also multiplies the
 *     final score by DOSE_PENALTY (0.6).
 *   - Dose tokens are excluded from tokenSimilarity/coverage: the dose axis is
 *     scored only through doseBonus/penalty, because sheet doses are spaced
 *     ("75 mg") while users type "75mg" and a literal token match would
 *     double-penalize a correct query.
 *   - MATCH_THRESHOLD = 0.72 decides a match; MAX_SUGGESTIONS = 3 caps the
 *     bioequivalent fallback list (RF-02).
 *
 * DELIBERATELY LLM-FREE: no Gemini/LLM node exists in this workflow, so RF-01
 * grounding (never invent names, prices or stock) is structural — every figure
 * in the reply is read from the sheets and recomputed here.
 *
 * LATENCY NOTE (risk R-01): the two Google Sheets reads (read_catalogo +
 * read_inventario) dominate end-to-end latency; caching the catalog in the
 * workflow is the planned optimization.
 */

const COVERAGE_TOKEN_MIN = 0.799;
const MATCH_THRESHOLD = 0.72;
const MAX_SUGGESTIONS = 3;
const DOSE_PENALTY = 0.6;

function normalize(s) {
  return String(s === null || s === undefined ? '' : s)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function tokenize(s) {
  const n = normalize(s);
  return n ? n.split(' ') : [];
}

function levenshteinDistance(a, b) {
  a = String(a === null || a === undefined ? '' : a);
  b = String(b === null || b === undefined ? '' : b);
  if (a === b) return 0;
  if (a.length === 0) return b.length;
  if (b.length === 0) return a.length;
  let prev = new Array(b.length + 1);
  let curr = new Array(b.length + 1);
  for (let j = 0; j <= b.length; j++) prev[j] = j;
  for (let i = 1; i <= a.length; i++) {
    curr[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const cost = a.charCodeAt(i - 1) === b.charCodeAt(j - 1) ? 0 : 1;
      curr[j] = Math.min(curr[j - 1] + 1, prev[j] + 1, prev[j - 1] + cost);
    }
    const tmp = prev;
    prev = curr;
    curr = tmp;
  }
  return prev[b.length];
}

function levenshteinSimilarity(a, b) {
  const left = String(a === null || a === undefined ? '' : a);
  const right = String(b === null || b === undefined ? '' : b);
  if (left.length === 0 && right.length === 0) return 1;
  if (left.length === 0 || right.length === 0) return 0;
  const maxLen = Math.max(left.length, right.length);
  return 1 - levenshteinDistance(left, right) / maxLen;
}

function isDoseToken(token) {
  return /^\d+(\.\d+)?$/.test(token) || /^\d+(\.\d+)?(mg|ml|g|ui|mcg)$/.test(token);
}

function parseDoseToken(token) {
  const m = /^(\d+(?:\.\d+)?)(mg|ml|g|ui|mcg)?$/.exec(String(token));
  return m ? { value: m[1], unit: m[2] || '' } : null;
}

/** Row dose matches the query dose token when the normalized dose tokens contain
 *  the token value (and the unit, when the token carries one), e.g. dose
 *  "75 mg" contains token "75" and token "75mg". */
function rowDoseMatches(rowDose, doseToken) {
  const parsed = parseDoseToken(doseToken);
  if (!parsed) return false;
  const doseTokens = tokenize(rowDose);
  if (doseTokens.indexOf(parsed.value) === -1) return false;
  if (!parsed.unit) return true;
  return doseTokens.indexOf(parsed.unit) !== -1;
}

/** Field-match shortcuts: exact = 1.0, starts with query = 0.92, contains = 0.85. */
function tokenSimilarity(queryToken, candidateToken) {
  if (queryToken === candidateToken) return 1;
  if (queryToken.length > 0 && candidateToken.indexOf(queryToken) === 0) return 0.92;
  if (queryToken.length > 0 && candidateToken.indexOf(queryToken) !== -1) return 0.85;
  return levenshteinSimilarity(queryToken, candidateToken);
}

function rowJson(item) {
  return item && item.json ? item.json : item;
}

function tokenPool(row) {
  const fields = [row.nombre_comercial, row.principio_activo, row.dosis]
    .map(normalize)
    .join(' ')
    .trim();
  return fields ? fields.split(' ') : [];
}

function isActiveRow(row) {
  return !!row && normalize(row.activo) === 'si';
}

/** Final score (0..1) of one catalog row for the given tokenized query. */
function scoreCandidate(queryTokens, queryDoseToken, row) {
  const pool = tokenPool(row);
  let sum = 0;
  let covered = 0;
  let scored = 0;
  for (let i = 0; i < queryTokens.length; i++) {
    const qt = queryTokens[i];
    if (isDoseToken(qt)) continue; // dose axis is scored via doseBonus/penalty only
    scored++;
    let best = 0;
    for (let j = 0; j < pool.length; j++) {
      const s = tokenSimilarity(qt, pool[j]);
      if (s > best) best = s;
    }
    sum += best;
    if (best >= COVERAGE_TOKEN_MIN) covered++;
  }
  const ts = scored ? sum / scored : 0;
  const coverage = scored ? covered / scored : 0;
  const doseMatched = queryDoseToken ? rowDoseMatches(row.dosis, queryDoseToken) : null;
  const doseBonus = queryDoseToken ? (doseMatched ? 1 : 0) : 0.5;
  let final = 0.60 * ts + 0.30 * coverage + 0.10 * doseBonus;
  if (queryDoseToken && !doseMatched) final *= DOSE_PENALTY;
  return final;
}

function inventoryMap(inventoryRows) {
  const map = new Map();
  const rows = inventoryRows || [];
  for (let i = 0; i < rows.length; i++) {
    const r = rowJson(rows[i]);
    if (r && r.medicamento_id !== undefined && r.medicamento_id !== null) {
      map.set(normalize(r.medicamento_id), r);
    }
  }
  return map;
}

/** stock_neto is ALWAYS recomputed here (stock_real - stock_reservado);
 *  the sheet's stock_neto formula column is never trusted. */
function stockNeto(row, inventoryById) {
  const inv = inventoryById.get(normalize(row.medicamento_id));
  if (!inv) return 0;
  const real = Number(inv.stock_real);
  const reserved = Number(inv.stock_reservado);
  return (isNaN(real) ? 0 : real) - (isNaN(reserved) ? 0 : reserved);
}

/**
 * Best active catalog row for a free-text query.
 * Returns { matched, score }: `matched` is the row only when score >= MATCH_THRESHOLD,
 * `score` is always the best score found (so callers/tests can assert on it).
 */
function matchMedicine(query, catalogRows) {
  const queryTokens = tokenize(query);
  let queryDoseToken = null;
  for (let i = 0; i < queryTokens.length; i++) {
    if (isDoseToken(queryTokens[i])) {
      queryDoseToken = queryTokens[i];
      break;
    }
  }
  const rows = (catalogRows || []).map(rowJson).filter(isActiveRow);
  let bestRow = null;
  let bestScore = 0;
  for (let i = 0; i < rows.length; i++) {
    const s = scoreCandidate(queryTokens, queryDoseToken, rows[i]);
    if (bestRow === null || s > bestScore) {
      bestRow = rows[i];
      bestScore = s;
    }
  }
  return {
    matched: bestRow !== null && bestScore >= MATCH_THRESHOLD ? bestRow : null,
    score: bestScore
  };
}

/** CLP with "." thousands separator and "$" prefix, e.g. formatClp(4500) === "$4.500". */
function formatClp(value) {
  const n = Math.round(Number(value) || 0);
  const digits = String(Math.abs(n));
  let grouped = '';
  for (let i = 0; i < digits.length; i++) {
    grouped += digits.charAt(i);
    const remaining = digits.length - 1 - i;
    if (remaining > 0 && remaining % 3 === 0) grouped += '.';
  }
  return (n < 0 ? '-' : '') + '$' + grouped;
}

/** Up to MAX_SUGGESTIONS active rows with stock: bioequivalente_de points at the
 *  matched row, OR same principio_activo AND same dosis (RF-02 fallback). */
function suggestionRows(matched, catalogRows, inventoryById) {
  const matchedId = normalize(matched.medicamento_id);
  const matchedActive = normalize(matched.principio_activo);
  const matchedDose = normalize(matched.dosis);
  const rows = (catalogRows || []).map(rowJson);
  const out = [];
  for (let i = 0; i < rows.length; i++) {
    const cand = rows[i];
    if (!isActiveRow(cand)) continue;
    if (normalize(cand.medicamento_id) === matchedId) continue;
    const byLink = normalize(cand.bioequivalente_de) === matchedId;
    const byMoiety =
      normalize(cand.principio_activo) === matchedActive &&
      normalize(cand.dosis) === matchedDose;
    if (!byLink && !byMoiety) continue;
    if (stockNeto(cand, inventoryById) <= 0) continue;
    out.push(cand);
    if (out.length >= MAX_SUGGESTIONS) break;
  }
  return out;
}

/**
 * Full Spanish reply for a query. Returns '' when nothing should be sent
 * (empty/non-text input). Never invents names, prices or stock numbers (RF-01).
 */
function buildReplyText(query, catalogRows, inventoryRows) {
  const q = String(query === null || query === undefined ? '' : query).trim();
  if (!q || !normalize(q)) return '';
  const inventoryById = inventoryMap(inventoryRows);
  const result = matchMedicine(q, catalogRows);

  if (result.matched) {
    const row = result.matched;
    const stock = stockNeto(row, inventoryById);
    const head =
      row.nombre_comercial + ' ' + row.dosis + ' — ' +
      formatClp(row.precio_unitario_clp) + ' c/u. Stock disponible: ' + stock + ' unidades.';
    if (stock > 0) return head;

    const alts = suggestionRows(row, catalogRows, inventoryById);
    if (alts.length === 0) {
      // No available bioequivalent: state it plainly, without naming any product.
      return 'Este producto no tiene stock disponible en este momento y no contamos con bioequivalentes disponibles con stock. Puede intentar nuevamente más tarde.';
    }
    let text =
      head + ' Producto agotado temporalmente. Bioequivalentes disponibles con stock:\n';
    for (let i = 0; i < alts.length; i++) {
      const a = alts[i];
      text +=
        '- ' + a.nombre_comercial + ' ' + a.dosis + ' — ' +
        formatClp(a.precio_unitario_clp) + ' c/u.\n';
    }
    return text.replace(/\n$/, '');
  }

  // No match (R-02 grounding): no product name, no price, no stock figure.
  return 'No encontré "' + q + '" en nuestro catálogo. Le sugiero reintentar con el nombre del principio activo (el genérico).';
}

// --- n8n data assembly -------------------------------------------------------
// Guarded: outside the editor (test harness) `$`/`$input` do not exist, so this
// block stays inert and only the named functions above are reachable.
if (typeof $ !== 'undefined' && typeof $input !== 'undefined') {
  const incoming = $('parse_incoming').first().json;
  const catalogRows = $('read_catalogo').all();
  const inventoryRows = $input.all();
  const text = incoming && incoming.text ? incoming.text : '';
  const message = buildReplyText(text, catalogRows, inventoryRows);
  if (!message) return []; // non-text input → empty array, nothing is sent
  return [{ json: { chat_id: incoming.chat_id, message: message } }];
}
